  + '  height?: string;\n'
  + '  h?: string;\n'
  + '  maxHeight?: string;\n'
  + '  maxH?: string;\n'
  + '  minHeight?: string;\n'
  + '  minH?: string;\n'
  + '};\n'
  + '\n'
  + 'function useStx(stylesProps: StylesProps) {\n'
  + '  const {\n'
  + '    width,\n'
  + '    w,\n'
  + '    maxWidth,\n'
  + '    maxW,\n'
  + '    minWidth,\n'
  + '    minW,\n'
  + '    height,\n'
  + '    h,\n'
  + '    maxHeight,\n'
  + '    maxH,\n'
  + '    minHeight,\n'
  + '    minH,\n'
  + '  } = stylesProps;\n'
  + '\n'
  + '  const resolvedWidth = width || w;\n'
  + '  const resolvedMaxWidth = maxWidth || maxW;\n'
  + '  const resolvedMinWidth = minWidth || minW;\n'
  + '  const resolvedHeight = height || h;\n'
  + '  const resolvedMaxHeight = maxHeight || maxH;\n'
  + '  const resolvedMinHeight = minHeight || minH;\n'
  + '\n'
  + '  const jss = useJss();\n'
  + '\n'
  + '  return jss.hash({\n'
  + '    width: resolvedWidth,\n'
  + '    maxWidth: resolvedMaxWidth,\n'
  + '    minWidth: resolvedMinWidth,\n'
  + '    height: resolvedHeight,\n'
  + '    maxHeight: resolvedMaxHeight,\n'
  + '    minHeight: resolvedMinHeight,\n'
  + '  });\n'
  + '}\n'
  + '\n'
